def px_to_world(u,v):
    s=.227185/256
    return -.1+(128-v)*s, (128-u)*s

def path_rows(points,z=.013):
    xy=[px_to_world(u,v) for u,v in points]
    x0,y0=xy[0];xe,ye=xy[-1]
    return [p(x0,y0,.055),p(x0,y0,z),p(x0,y0,z)]+[p(x,y,z) for x,y in xy[1:]]+[p(xe,ye,z),p(xe,ye,.055)]

def send_batched(rows,prefix):
    batch=[];t=0;prev=np.array(r.get_obs(cameras=['canvas_cam'],video='none').group('tcp_pose',now=True)[:3])
    num=0
    for row in rows:
        pos=np.array(row[:3]);inc=max(.25,float(np.linalg.norm(pos-prev))/.24)
        if batch and (t+inc>7.5 or len(batch)>=25):
            submit_rows(batch,f'{prefix}_{num:03d}',dt=.25);num+=1;batch=[];t=0
        batch.append(row);t+=inc;prev=pos
    if batch: submit_rows(batch,f'{prefix}_{num:03d}',dt=.25)

def paint_paths():
    import json
    paths=json.load(open('/app/output/paths.json'))
    order=[2,3,4,5,7,8,10,6,9]
    for c in order:
        dip(c)
        cpaths=[x for x in paths if x['c']==c]
        print('COLOR',c,'paths',len(cpaths),flush=True)
        for j,path in enumerate(cpaths):
            send_batched(path_rows(path['points']),f'c{c:02d}p{j:03d}')
        travel(-.16,.145,.07)
        o=r.get_obs(cameras=['canvas_cam'],video='none');Image.fromarray(o.last['canvas_cam']).save(f'/app/output/color{c:02d}.jpg')
        print('STATUS',r.status(),flush=True)

if __name__=='__main__' and len(sys.argv)>1 and sys.argv[1]=='paint': paint_paths()
